mapper.insert:
INSERT INTO travel_plans (
    created_by_user_id, title, start_date, end_date,
    representative_image_url, status
) VALUES (
    #{createdByUserId}, #{title}, #{startDate}, #{endDate},
    #{representativeImageUrl}, #{status}
)

INSERT INTO travel_plan_members (
    travel_plan_id, user_id, display_name, role, status
) VALUES (
    #{travelPlanId}, #{userId}, #{displayName}, #{role}, #{status}
)

mapper.select:
SELECT id, created_by_user_id, title, start_date, end_date,
       representative_image_url, status, last_activity_at, finalized_at,
       created_at, updated_at
FROM travel_plans
WHERE id = #{travelPlanId}
  AND status = #{planStatus}

SELECT id, travel_plan_id, user_id, display_name, role, status,
       rejoin_allowed, joined_at, left_at, removed_at, created_at, updated_at
FROM travel_plan_members
WHERE travel_plan_id = #{travelPlanId}
  AND user_id = #{userId}
  AND status = #{memberStatus}
